import React, { useEffect, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import api, { getImageUrl } from '../../api/api.js';
import { useAuth } from '../../context/AuthContext.jsx';
import './SliderHome.css';

const FALLBACK_SLIDES = [
  {
    _id: 'fallback-2',
    title: 'Map Your Career Path',
    subtitle: 'Assessments, KCET & PGCET predictors, and admission support — in one place.',
    imageDesktop: '/images/hero-2-desktop.webp',
    imageMobile: '/images/hero-2-mobile.webp',
    ctaLink: '/subscription',
  },
];

const HERO_PILLS = [
  { to: '/career-assessment', label: 'Assessment', icon: '🧭', tone: 'amber' },
  { to: '/kcet-predictor', label: 'KCET', icon: '🎓', tone: 'blue' },
  { to: '/pgcet-predictor', label: 'PGCET', icon: '📘', tone: 'green' },
  { to: '/college-compare', label: 'Compare', icon: '⚖️', tone: 'lilac' },
  { to: '/college-admission-enquiry', label: 'Admission', icon: '🤝', tone: 'sky' },
];

export default function SliderHome() {
  const [slides, setSlides] = useState(FALLBACK_SLIDES);
  const [active, setActive] = useState(0);
  const [email, setEmail] = useState('');
  const navigate = useNavigate();
  const { student } = useAuth();

  useEffect(() => {
    api.get('/sliders').then((res) => {
      if (res.data.sliders && res.data.sliders.length) setSlides(res.data.sliders);
    }).catch(() => {});
  }, []);

  useEffect(() => {
    const timer = setInterval(() => setActive((a) => (a + 1) % slides.length), 5500);
    return () => clearInterval(timer);
  }, [slides.length]);

  const slide = slides[active] || slides[0];
  if (!slide) return null;

  const desktopSrc = getImageUrl(slide.imageDesktop || slide.image);
  const mobileSrc = getImageUrl(slide.imageMobile || slide.image);
  const isFirstPaint = active === 0;
  const isImageOnly = !!slide.imageOnly;

  const goToSlideLink = () => {
    if (isImageOnly || !slide.ctaLink) return;
    navigate(slide.ctaLink);
  };

  const submitEmail = (e) => {
    e.preventDefault();
    e.stopPropagation();
    if (student) {
      navigate('/dashboard');
      return;
    }
    const next = email.trim()
      ? `/register?email=${encodeURIComponent(email.trim())}`
      : '/register';
    navigate(next);
  };

  const picture = (
    <picture>
      <source media="(max-width: 768px)" srcSet={mobileSrc} />
      <img
        src={desktopSrc}
        alt={slide.title || 'MapMyCareer360'}
        className="mmc-slider-img mmc-kenburns"
        fetchPriority={isFirstPaint ? 'high' : 'auto'}
        loading={isFirstPaint ? 'eager' : 'lazy'}
        decoding={isFirstPaint ? 'sync' : 'async'}
      />
    </picture>
  );

  const dots = slides.length > 1 && (
    <div className="mmc-slider-dots" onClick={(e) => e.stopPropagation()}>
      {slides.map((s, i) => (
        <button
          key={s._id || i}
          className={i === active ? 'active' : ''}
          onClick={() => setActive(i)}
          aria-label={`Go to slide ${i + 1}`}
        />
      ))}
    </div>
  );

  if (isImageOnly) {
    return (
      <section
        className="mmc-slider mmc-slider--image-only"
        aria-label={slide.title || 'MapMyCareer360'}
      >
        <div className="mmc-slider-bg">{picture}</div>
        {dots}
      </section>
    );
  }

  return (
    <section className="mmc-hero" aria-label={slide.title || 'MapMyCareer360'}>
      <div className="container mmc-hero-grid">
        <div className="mmc-hero-copy" key={slide._id || active}>
          <p className="mmc-hero-stats">1,000+ Students guided · 150+ Colleges · 24/7 Support</p>
          <h1>{slide.title || 'Map Your Career Path'}</h1>
          <p className="mmc-hero-sub">{slide.subtitle}</p>

          {student ? (
            <div className="mmc-hero-actions">
              <Link to="/dashboard" className="btn btn-ink">
                Open dashboard
                <span aria-hidden="true">→</span>
              </Link>
              {slide.ctaLink && (
                <button type="button" className="btn btn-outline" onClick={goToSlideLink}>
                  Explore now
                </button>
              )}
            </div>
          ) : (
            <form className="mmc-hero-signup" onSubmit={submitEmail}>
              <label className="sr-only" htmlFor="mmc-hero-email">Email</label>
              <input
                id="mmc-hero-email"
                type="email"
                name="email"
                placeholder="Enter your email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                autoComplete="email"
              />
              <button type="submit" className="btn btn-ink">
                Sign up for free
                <span aria-hidden="true">→</span>
              </button>
            </form>
          )}
        </div>

        <div className="mmc-hero-visual">
          {slide.ctaLink ? (
            <button
              type="button"
              className="mmc-hero-frame"
              onClick={goToSlideLink}
              aria-label={`Open ${slide.title || 'slide'}`}
            >
              {picture}
            </button>
          ) : (
            <div className="mmc-hero-frame">{picture}</div>
          )}
          <span className="mmc-hero-chip mmc-hero-chip--tl mmc-float">Free career assessment</span>
          <span className="mmc-hero-chip mmc-hero-chip--br mmc-float">Plans from ₹1</span>
        </div>
      </div>

      <div className="container mmc-hero-pills">
        {HERO_PILLS.map((pill) => (
          <Link key={pill.to} to={pill.to} className={`mmc-hero-pill mmc-hero-pill--${pill.tone}`}>
            <span className="mmc-hero-pill-icon" aria-hidden="true">{pill.icon}</span>
            <span>{pill.label}</span>
          </Link>
        ))}
      </div>
      {dots}
    </section>
  );
}
